# tron's defaults. Do not edit this file: override in settings/override/tron.ini.append.php or a siteaccess.
# Every setting is described in doc/configuration.md.

[ServerSettings]
Title=Exponential tron
# Extra text appended to the instructions of the initialize answer
Instructions=
# Tools per tools/list page
PageSize=100
# Answers above this size are cut, with a note to page with limit/offset
ResponseMaxBytes=200000

[ProgramSettings]
# enabled: look for tron/program.json in every active extension; disabled: tron's own programs only
ExtensionScan=enabled
# Programs to leave out, by name (the core program "tron" cannot be left out)
Disabled[]

[AuditSettings]
# database (table tron_audit) and/or file (JSON lines). tron refuses to start without a sink, and a write tool does
# not run when its "started" entry cannot be written.
Sinks[]
Sinks[]=database
FilePath=var/log/tron-audit.log

[JournalSettings]
# The activity journal (doc/activity-journal.md): every MCP session and background job as a story with its steps,
# what each call touched, the diff of each write and a hash chain per session. Setup > tron > Activity shows it; the
# tools tron_journal_note, _list, _show and _search reach it. enabled or disabled.
Enabled=enabled
# An HTTP client's requests belong to one session while they come within this many minutes of each other; an open
# session idle longer than this is closed by tron-journal.php rotate.
IdleMinutes=30
# Sessions whose last activity is older than this are removed by tron-journal.php rotate (0: keep everything).
RetentionDays=180
# enabled: a removed session is first appended, steps and chain check included, to <ArchiveDir>/tron-journal-<YYYY-MM>.jsonl
Archive=enabled
ArchiveDir=var/log/tron-journal
# enabled: a write's diff (from its dry run, or what the tool attached) is stored with the step, redacted and cut at
# MaxDiffBytes; disabled: only the pointer (plan:<id>) is kept
StoreDiffs=enabled
MaxDiffBytes=20000
# The result summary of a step, in characters
MaxResultChars=300
# The arguments of a step as stored (already redacted like the audit), in bytes
MaxInputBytes=8000
# enabled: a write tool does not run when its "started" step cannot be journaled (like the audit log);
# disabled: a journal failure is logged and the call goes on (the audit log still has it)
Required=disabled

[TokenSettings]
DefaultLifetimeDays=90
MaxLifetimeDays=365

[StdioSettings]
# disabled (the default): tron.php serve needs a token on stdio too, TRON_TOKEN=<token> or --token-file=<file>
# (tron.php token:create makes one), and serve --user=<login> is refused. Without a token, --user would let whoever
# can start the process act as any user, an administrator included.
# enabled: serve --user=<login> is allowed without a token. Set it only in settings/override, only where every
# account that can run tron.php may act as every user anyway.
AllowLoginOption=disabled

[HTTPSettings]
# The endpoint /tron/mcp answers 404 until this is true and the siteaccess is listed
Enabled=false
SiteAccesses[]
# Browser origins allowed to call (scheme://host[:port]); empty: a request with an Origin header is refused
AllowedOrigins[]
# Host names served (empty: any); set it on a public endpoint, e.g. centre.se7enx.com
AllowedHosts[]
MaxBodyBytes=1048576

[CentreSettings]
# auto: centre's own API when the extension expcentre is active here (centre.se7enx.com), else tron's tables;
# expcentre: only centre's API (tools left out without it); tron: only tron's tables tron_centre_*
Backend=auto
# tron's tables only: the lanes of every board, in board order; new tickets go to the first
Lanes[]
Lanes[]=inbox
Lanes[]=next
Lanes[]=doing
Lanes[]=waiting
Lanes[]=done
# The boards that exist; empty: any board name (a-z, 0-9, -)
Boards[]

[KatalystSettings]
# kernel: read through sevenx_katalyst's classes when that extension is active here; none: leave the tools out
Source=kernel

[McpEngineSettings]
# MCP engines: extensions that serve tools to tron and, through tron, to hosts such as expai's assistant. Each one is
# a group [McpEngine_<id>] (id a-z0-9, at most 20 characters; "tron" is tron itself, "mcp" is reserved), shipped in
# the extension's own settings/tron.ini.append.php, so activating the extension is enough. Its tools are offered as
# <id>__<tool>; tron checks the caller's policies and writes every call to the audit log. See doc/mcp-engines.md.
#
#   [McpEngine_<id>]
#   Class=<a class implementing tronMcpEngine, or a class of the bridge API>
#   Enabled=enabled
#   Label=<shown in tool descriptions and Setup > tron>
#   ReadPolicy=<module/function a read tool without its own policy needs; empty: none>
#   WritePolicy=<module/function a write tool without its own policy needs; empty: no write tools>
#
# enabled: classes the interface scan finds (tron-engines.php --scan) and no group names are registered too, under an
# id made from the class name. The scan reads the extension autoload array on every server build; leave it off and
# register engines by INI unless you are trying one out.
ScanRegister=disabled

# tron itself, the tools of its programs (tron__<tool> to hosts). Always there while tron is active.
[McpEngine_tron]
Class=tronMcpTronEngine
Label=tron

[PromptRules]
# The agent rules layer (doc/agent-rules.md): the site's AGENTS.md and the Exponential MASTER.md, served to agents as
# tron://rules/* and the prompt tron_project_rules, and appended to the instructions of every session. MASTER.md
# supersedes AGENTS.md where the two conflict.
# The site's prompt directory, holding AGENTS.md, a MASTER.md override, MASTER.disabled and rules-state.json.
# Empty: <VarDir>/storage/claude/prompt of the siteaccess (var/site/storage/claude/prompt on a standard installation).
Directory=
# The MASTER.md used when the prompt directory has none. Empty: tron's own doc/MASTER.md.
DefaultMaster=
# MASTER.md for the site: enabled or disabled. A siteaccess's tron.ini.append.php can set it per siteaccess. Above it
# in precedence: the file marker MASTER.disabled, the environment variable TRON_MASTER_RULES, the admin toggle.
Master=enabled
# The site's AGENTS.md: enabled or disabled
Agents=enabled
# enabled: the rules are appended to the instructions of initialize; disabled: only the resources and the prompt
Instructions=enabled
# The rules in the instructions are cut here (the resource tron://rules/combined always has all of them)
InstructionsMaxBytes=40000
# The largest rules file Setup > tron > Agent rules accepts and tron reads
MaxBytes=200000
# The installation's private names (internal servers, hosts, projects) and internal domains. When MASTER.md is
# generated from AGENTS.md, a line naming one is left out and a domain becomes an example.org name; the check reports
# both. Set them in settings/override only, never in a file that is shipped; tron ships none.
PrivateNames[]
PrivateDomains[]

[PlanSettings]
# Dry runs (tron_plan, doc/dry-run.md): how long a plan can be applied with tron_apply, in seconds (10 to 3600)
LifetimeSeconds=300

[RedactionSettings]
# enabled: every answer (tool results and errors, resources, prompts, instructions) passes the redactor, and the audit
# records the kinds and counts it masked (doc/redaction.md); disabled: answers go out as the tools give them (a closed
# test installation only; the audit's own masking stays)
Output=enabled
# The kinds to mask: secret, token, key, dsn, email, phone; empty: all
Kinds[]

# ---- The root programs web, browser, validate, diff, api (doc/root-programs.md) ----

[RootProgramSettings]
# enabled: the five root programs offer their tools; disabled (or missing): they load but leave every tool out
Enabled=enabled

[WebSettings]
# enabled: tron may make outbound requests (web, validate_links, api, browser jobs). Without this setting it is off.
Network=enabled
# Seconds for a whole request, bytes read at most (the rest is cut), redirects followed (each hop checked again)
Timeout=15
MaxBytes=2097152
MaxRedirects=5
# Ports besides 80 and 443 a request may use
AllowedPorts[]
# Hosts the SSRF guard lets through although they resolve to a private address (an exact host or *.domain). The only
# exception there is; keep it empty unless an intranet server must be reached on purpose.
PrivateHosts[]
# The installation's private mesh (IPv4 CIDRs, e.g. 10.0.0.0/16): addresses there are refused as "mesh" rather than
# "private", and MASTER.md generation replaces them. Set it in settings/override only; tron ships none.
MeshNetworks[]
# enabled: robots.txt is respected (RFC 9309, product token "tron")
RespectRobots=enabled
# Public GET answers and robots.txt files are cached this many seconds (0: off), under CacheDir
CacheTTL=600
CacheDir=var/cache/tron/web

[BrowserSettings]
# The nodes that run browser jobs (hostname as gethostname() gives it). Elsewhere the browser tools are left out.
RunnerHosts[]
# tron's own directory of browser engines (engines.json records what is installed); owned by the runner's user
BrowsersPath=/var/lib/tron/browsers
# The job queue, relative to the installation (queue/, running/, done/, artifacts/)
QueueDir=var/tron/browser
# The Playwright version the engines are pinned to (the runner's)
PlaywrightVersion=1.60.0
# chromium (headless shell), chrome (Chrome for Testing), firefox, webkit
DefaultEngine=chromium

[ValidateSettings]
# validate_php: where the copy to lint is written, the PHP command line binary (empty: this PHP), the time limit
SandboxDir=var/tmp/tron-validate
PhpBinary=
PhpLintTimeout=10

[ApiSettings]
# The address of this installation for api_rest_v1, api_rest_v2, api_rest_v2_write and api_graphql (empty: those
# tools are left out), e.g. https://www.example.com
BaseUrl=
# Secret names (Setup > Secrets, expSecrets) a call may name as key_secret or in secrets[]; values never leave tron
SecretNames[]
# Hosts api_http_request may reach (exact host or *.domain); empty: none
AllowedHosts[]

[SkillPackSettings]
# Skills: reviewed chains of units as data, in packs (doc/skills.md, doc/extension-conventions.md).
# enabled: tron's own packs in share/skills are loaded
TronPacks=enabled
# enabled: active extensions are scanned for tron/skills/<pack>/pack.json; each pack needs its group
#   [SkillPack_<id>] Extension=<ext> Path=tron/skills/<id> Enabled=enabled
# in the extension's own settings/tron.ini.append.php
ExtensionScan=enabled
# Pack ids to leave out
Disabled[]

*/ ?>
